INSERT INTO "lemma_corrections" VALUES('H1419','גָּדוֹל','TAHOT''s lemma field reads גַּל (gal, a heap) for 512 of the 526 words of H1419 gadol, great, and גָּדוֹל for 14; the words themselves are gadol, gedola, gedolim','2026-10-27');
