-- Word Atlas metadata.db backup (plain SQL; restore with atlas_backup.py)
-- written: 2026-10-27 11:00
BEGIN TRANSACTION;
CREATE TABLE books (
    book_num       INTEGER PRIMARY KEY,     -- 1 = Genesis ... 66 = Revelation
    name           TEXT NOT NULL UNIQUE,
    testament      TEXT NOT NULL CHECK (testament IN ('OT', 'NT')),
    genre          TEXT NOT NULL,
    baseline_group TEXT NOT NULL,
    source_note    TEXT NOT NULL DEFAULT ''
);
CREATE TABLE context_names (
    layer      TEXT NOT NULL,      -- content or orientation
    testament  TEXT NOT NULL,      -- Old or New
    number     INTEGER NOT NULL,   -- the context's number when it was named
    name       TEXT NOT NULL,      -- the reader's name for it
    words      TEXT NOT NULL,      -- its marking words then, comma separated
    saved      TEXT NOT NULL,      -- when it was stored
    PRIMARY KEY (layer, testament, number)
);
CREATE TABLE corpora (
    corpus      TEXT PRIMARY KEY,
    language    TEXT NOT NULL CHECK (language IN ('Hebrew', 'Greek')),
    description TEXT NOT NULL DEFAULT '',
    source_note TEXT NOT NULL DEFAULT ''
);
CREATE TABLE feeling_words (
        root      TEXT PRIMARY KEY,   -- Strong's number, e.g. H2534
        category  TEXT NOT NULL,      -- anger, grief, ... (see atlas_feelings.py)
        family    TEXT NOT NULL,      -- emotion, senses, body, violence, wealth, harlotry
        note      TEXT                -- the gloss at review time, for reading the table
    );
CREATE TABLE hebrew_verse_map (book TEXT, heb_chapter INTEGER, heb_verse INTEGER, chapter INTEGER, verse INTEGER, note TEXT, PRIMARY KEY (book, heb_chapter, heb_verse));
CREATE TABLE lemma_corrections (
    strongs TEXT PRIMARY KEY,      -- the Strong's number, H1419
    lemma   TEXT NOT NULL,         -- the dictionary form it should have, pointed
    reason  TEXT NOT NULL,         -- what the tagged text has, and why it is wrong
    added   TEXT NOT NULL          -- the date the row was added
);
CREATE TABLE lexicon_forms (
    strongs       TEXT PRIMARY KEY,       -- the Strong's number, H6635
    script        TEXT NOT NULL,          -- the word in Hebrew or Greek, pointed or accented, cantillation off
    translit      TEXT NOT NULL,          -- the transliteration printed: tsava
    translit_long TEXT NOT NULL,          -- with the long vowels marked: tsāvā
    language      TEXT NOT NULL,          -- Hebrew, Aramaic or Greek
    source        TEXT NOT NULL,          -- TAHOT, GNT, LXX or lexicon
    translit_text TEXT NOT NULL,          -- the word as it stands in the text, prefixes removed: vohu (translit: bohu)
    attested_share REAL,                  -- the share of the occurrences the printed form holds; blank where not counted
    script_text   TEXT NOT NULL DEFAULT '' -- the Hebrew letters that follow translit_text: בֹהוּ (script: בֹּהוּ)
);
CREATE TABLE lxx_books (
    code        TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    book_num    INTEGER REFERENCES books(book_num),
    variant     TEXT NOT NULL DEFAULT '',
    preferred   INTEGER NOT NULL DEFAULT 0 CHECK (preferred IN (0, 1)),
    canon_order INTEGER NOT NULL DEFAULT 0,
    chapters    INTEGER NOT NULL DEFAULT 0,
    verses      INTEGER NOT NULL DEFAULT 0,
    source_note TEXT NOT NULL DEFAULT ''
);
CREATE TABLE lxx_chapter_map (
    book_num    INTEGER NOT NULL REFERENCES books(book_num),
    eng_chapter INTEGER NOT NULL,
    lxx_chapter INTEGER NOT NULL,
    source_note TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (book_num, eng_chapter)
);
CREATE TABLE lxx_verse_map (
    book_num    INTEGER NOT NULL REFERENCES books(book_num),
    eng_chapter INTEGER NOT NULL,
    eng_verse   INTEGER NOT NULL,
    lxx_code    TEXT NOT NULL,
    lxx_chapter INTEGER,
    lxx_verse   INTEGER,
    origin      TEXT NOT NULL CHECK (origin IN ('tvtms', 'manual')),
    review      INTEGER NOT NULL DEFAULT 0 CHECK (review IN (0, 1)),
    source_note TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (book_num, eng_chapter, eng_verse)
);
CREATE TABLE meta_info (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
CREATE TABLE passage_ranges (
    passage_id    INTEGER NOT NULL REFERENCES passages(passage_id) ON DELETE CASCADE,
    book_num      INTEGER NOT NULL REFERENCES books(book_num),
    chapter_start INTEGER NOT NULL,
    verse_start   INTEGER NOT NULL,
    chapter_end   INTEGER NOT NULL,
    verse_end     INTEGER NOT NULL,
    UNIQUE (passage_id, book_num, chapter_start, verse_start)
);
CREATE TABLE passages (
    passage_id  INTEGER PRIMARY KEY AUTOINCREMENT,
    name        TEXT NOT NULL UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    source_note TEXT NOT NULL DEFAULT ''
);
CREATE TABLE root_equivalents (
    root        TEXT PRIMARY KEY,
    group_root  TEXT NOT NULL,
    source_note TEXT NOT NULL DEFAULT ''
);
CREATE TABLE tradition_verse_map (tradition TEXT, book TEXT, chapter INTEGER, verse INTEGER, kjv_chapter INTEGER, kjv_verse INTEGER, note TEXT, PRIMARY KEY (tradition, book, chapter, verse));
CREATE TABLE translation_families (abbreviation TEXT PRIMARY KEY, name TEXT, year INTEGER, family TEXT, distance_kjv REAL, note TEXT, edition TEXT);
CREATE TABLE translation_spellings (word TEXT PRIMARY KEY, spelled TEXT);
CREATE TABLE verse_tags (
    book_num    INTEGER NOT NULL REFERENCES books(book_num),
    chapter     INTEGER NOT NULL,
    verse       INTEGER NOT NULL,
    tag_type    TEXT NOT NULL,
    tag_value   TEXT NOT NULL,
    source_note TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (book_num, chapter, verse, tag_type, tag_value)
);
CREATE TABLE word_lists (
        list      TEXT NOT NULL,      -- character, divine, fruit, flesh (see atlas_feelings.py)
        root      TEXT NOT NULL,      -- Strong's number, e.g. H6662
        note      TEXT,               -- the plain word, for reading the table
        PRIMARY KEY (list, root)
    );
CREATE INDEX idx_verse_tags_type_value
    ON verse_tags (tag_type, tag_value);
DELETE FROM "sqlite_sequence";
COMMIT;
